def get_from_cache(db_name: str, cache_valid_seconds: int=0,
    skip_time_verification: bool=False) ->Optional[Dict[str, Any]]:
    if not os.path.exists(DB_CACHE_FILE):
        return None

    try:
        with open(DB_CACHE_FILE, "r") as f:
            cache = json.loads(f.read())
    except (json.JSONDecodeError, OSError):
        return None

    if db_name not in cache:
        return None

    db_cache = cache[db_name]
    cached_at = db_cache.get("cached_at")

    if not cached_at:
        return None

    if not skip_time_verification:
        if cache_valid_seconds > 0:
            if time.time() - cached_at > cache_valid_seconds:
                return None

    return db_cache.get("db")
